```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("macierz.txt");
    int m[4][4];
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4; j++)
            plik >> m[i][j];
    cout << "Minimum w kazdym wierszu:" << endl;
    for (int i = 0; i < 4; i++) {
        int mn = m[i][0], mnJ = 0;
        for (int j = 1; j < 4; j++) {
            if (m[i][j] < mn) { mn = m[i][j]; mnJ = j; }
        }
        cout << "   Wiersz " << i + 1 << ": " << mn << " (kolumna " << mnJ + 1 << ")" << endl;
    }
    cout << "Maksimum w kazdej kolumnie:" << endl;
    for (int j = 0; j < 4; j++) {
        int mx = m[0][j], mxI = 0;
        for (int i = 1; i < 4; i++) {
            if (m[i][j] > mx) { mx = m[i][j]; mxI = i; }
        }
        cout << "   Kolumna " << j + 1 << ": " << mx << " (wiersz " << mxI + 1 << ")" << endl;
    }
    cout << "Punkty siodlowe:" << endl;
    bool found = false;
    for (int i = 0; i < 4; i++) {
        int mn = m[i][0], mnJ = 0;
        for (int j = 1; j < 4; j++) {
            if (m[i][j] < mn) { mn = m[i][j]; mnJ = j; }
        }
        int mx = m[0][mnJ];
        for (int ii = 1; ii < 4; ii++) {
            if (m[ii][mnJ] > mx) mx = m[ii][mnJ];
        }
        if (mn == mx) {
            cout << "   (" << i + 1 << ", " << mnJ + 1 << ") = " << mn << endl;
            found = true;
        }
    }
    if (!found) cout << "   Brak" << endl;
    return 0;
}
```

Weryfikacja:
- Wiersz 1 min: 3 (kol 1). Kol 1 max: 5 (w2). 3≠5.
- Wiersz 2 min: 5 (kol 1). Kol 1 max: 5 (w2). 5==5 → punkt siodlowy (2,1)=5!
- Wiersz 3 min: 1 (kol 3). Kol 3 max: 7 (w2). 1≠7.
- Wiersz 4 min: 2 (kol 4). Kol 4 max: 9 (w2). 2≠9.
